--- Normalise a spec into a table with src/dir, name, version
---@param item PackSpecItem A plugin spec as string or table
---@return PackSpec Normalised plugin spec
local function normalise_spec(item)
  if type(item) == "string" then
    item = { src = item }
  end

  if item.dir then
    local dir = vim.fn.expand(item.dir):gsub("/+$", "")
    item.dir = dir
    item.name = item.name or dir:match("[^/]+$")
    return item
  end

  local src = item.src or item[1]
  if src then
    if src:match("^file://~/") then
      src = "file://" .. vim.fn.expand("~") .. src:sub(9)
    elseif not src:match("^[%w+.-]+://") and not src:match("^git@") and src:match("/") then
      src = "https://github.com/" .. src
    end
    item.src = src
    item.name = item.name or src:gsub("/+$", ""):gsub("%.git$", ""):match("[^/]+$")
  end

  item.version = item.branch or item.version
  return item
end

--- Recursively flatten a list of specs
---@param specs PackSpecList Nested or flat list of plugin specs
---@param out? PackSpec[] Output accumulator list
---@return PackSpec[] Flat list of normalised plugin specs
local function flatten_spec(specs, out)
  out = out or {}
  for _, item in ipairs(specs) do
    if type(item) == "string" then
      table.insert(out, normalise_spec(item))
    elseif type(item) == "table" then
      if item.src or item.dir or (type(item[1]) == "string" and #item == 1) then
        table.insert(out, normalise_spec(item))
      elseif type(item[1]) == "string" and #item > 1 then
        table.insert(out, normalise_spec(item))
        for i = 2, #item do
          table.insert(out, normalise_spec(item[i]))
        end
      else
        flatten_spec(item, out)
      end
    end
  end
  return out
end

--- Define the keymaps
---
--- Either a function is given, which is just executed or a table with the key specifications.
---@param keys PackKeymaps Keymap definition function or table of mappings
local function set_keymaps(keys)
  if type(keys) == "function" then
    keys()
  elseif type(keys) == "table" then
    for k, v in pairs(keys) do
      if type(k) == "number" and type(v) == "table" then
        vim.keymap.set(v.mode or "n", v[1], v[2], { desc = v.desc, buffer = v.buffer, silent = v.silent ~= false })
      elseif type(k) == "string" then
        local rhs = type(v) == "table" and (v.rhs or v[1]) or v
        local mode = (type(v) == "table" and v.mode) or "n"
        local desc = type(v) == "table" and v.desc or nil
        vim.keymap.set(mode, k, rhs, { desc = desc })
      end
    end
  end
end

